  1	/**
  2	 * ЕДИНЫЙ КОНФИГ цифрового двойника карьера Актогай.
  3	 *
  4	 * Модель построена по мотивам открытых данных о медном месторождении Актогай (Восточный Казахстан).
  5	 * ВСЕ числовые значения ниже — ОЦЕНКА, сверить с открытыми источниками (годовые отчёты KAZ Minerals).
  6	 * Операционные данные (поломки, очереди, расход) смоделированы и не являются данными предприятия.
  7	 *
  8	 * Моделируется не весь карьер, а «сегмент» парка: 10–30 самосвалов и 5 экскаваторов,
  9	 * поэтому план смены и производительность фабрики масштабированы под этот сегмент.
 10	 */
 11	import type { Material } from './types';
 12	
 13	export interface ExcavatorSpec {
 14	  name: string;
 15	  material: Material;
 16	  /** Производительность погрузки, т/мин. */
 17	  rateTpm: number;
 18	  /** Среднее содержание меди в забое, % (0 — вскрыша). Оценка. */
 19	  gradePct: number;
 20	  /** Индекс кольцевой дороги-бермы (1 — верхняя, 3 — дно карьера). */
 21	  ring: number;
 22	  /** Угол расположения забоя на берме, градусы (0 — восток, 90 — юг на экране). */
 23	  angleDeg: number;
 24	  /** Выработка (индекс в SimConfig.pits): 0 — главный карьер. */
 25	  pit?: number;
 26	}
 27	
 28	/** Выработка: чаша с уступами, своими спиральными съездами и кольцевыми бермами. */
 29	export interface PitSpec {
 30	  name: string;
 31	  /** Центр и поворот длинной оси в координатах модели, м и градусы. */
 32	  cx: number;
 33	  cy: number;
 34	  rotDeg: number;
 35	  /** Полуоси по бровке, м. */
 36	  semiMajorM: number;
 37	  semiMinorM: number;
 38	  /** Глубина, м, и число уступов (по 15 м). */
 39	  depthM: number;
 40	  benchCount: number;
 41	  /** Масштаб дна относительно бровки. */
 42	  bottomScale: number;
 43	  /** Витков спирального съезда от бровки до дна, узлов на съезде. */
 44	  rampTurns: number;
 45	  rampNodes: number;
 46	  /** Уровни кольцевых берм в долях глубины (0 — бровка, 1 — дно); должны попадать в узлы съезда. */
 47	  ringLevels: number[];
 48	  /** Узлов на кольце (кратно числу съездов). */
 49	  ringNodes: number;
 50	  /** Съезды: начальные углы (равномерно по кругу) и названия. */
 51	  rampStartsDeg: number[];
 52	  rampNames: string[];
 53	  /** Фаза неровности контура (чтобы выработки не были одинаковыми). */
 54	  warpPhase: number;
 55	}
 56	
 57	export interface Point {
 58	  x: number;
 59	  y: number;
 60	}
 61	
 62	export interface SimConfig {
 63	  shift: {
 64	    /** Длительность смены, с (12 ч). */
 65	    durationSec: number;
 66	    /** Шаг симуляции, с. Фиксированный — для детерминизма. */
 67	    tickSec: number;
 68	    /** Интервал записи истории для графиков, с. */
 69	    historyEverySec: number;
 70	  };
 71	  pit: {
 72	    /** Полуоси карьера по бровке, м. Оценка: карьер вытянутой формы ~3 × 1.6 км. */
 73	    semiMajorM: number;
 74	    semiMinorM: number;
 75	    /** Число уступов (для отрисовки). */
 76	    benchCount: number;
 77	    /** Масштаб дна относительно бровки. */
 78	    bottomScale: number;
 79	    /** Сколько витков делает спиральный съезд от бровки до дна. */
 80	    rampTurns: number;
 81	    /** Число узлов на каждом съезде (шаг 0.05 по глубине). */
 82	    rampNodes: number;
 83	    /** Уровни кольцевых берм в долях глубины (0 — бровка, 1 — дно). Должны попадать в узлы съезда. */
 84	    ringLevels: number[];
 85	    /** Узлов на каждом кольце (чётное число). */
 86	    ringNodes: number;
 87	  };
 88	  /**
 89	   * Выработки карьера — как на спутниковом снимке Актогая (31.03.2025): главный карьер, северо-западный
 90	   * и юго-западный. pits[0] — главный (его форма продублирована в pit для старого кода).
 91	   */
 92	  pits: PitSpec[];
 93	  /** Поверхностные объекты, м (центр карьера — 0,0). */
 94	  sites: {
 95	    crusher: Point;
 96	    plant: Point;
 97	    /** Склад дроблёной руды (конус) и изломы конвейеров: дробилка → склад и склад → фабрика. */
 98	    stockpile: Point;
 99	    conveyorVia: Point[];
100	    plantVia: Point[];
101	    leach: Point;
102	    /** Пруды растворов и завод SX-EW — оксидная ветка после выщелачивания. */
103	    ponds: Point;
104	    sxew: Point;
105	    /**
106	     * Вторая цепочка комбината (ККД-2 → склад → ОФ-2): в расчёте не участвует, нужна карте и 3D —
107	     * моделируемый сегмент парка возит руду на первую. Изломы конвейера склад → ОФ-2 — по OSM.
108	     */
109	    crusher2: Point;
110	    stockpile2: Point;
111	    plant2: Point;
112	    plant2Via: Point[];
113	    /** Подстанции фабрик и ЛЭП между ними и потребителями (полилинии; расположение условное). */
114	    sub: Point;
115	    sub2: Point;
116	    powerLines: [number, number][][];
117	    /** Склад концентрата у ж/д и трасса железной дороги (станция — фабрики — промзона). */
118	    conc: Point;
119	    rail: [number, number][];
120	    /** Хвостохранилище: центр чаши, контур ограждающей дамбы и трасса пульпопровода с ОФ-1. */
121	    tsf: Point;
122	    tsfOutline: [number, number][];
123	    pulpVia: Point[];
124	    waste: Point;
125	    /** Дополнительные отвалы вскрыши (на реальном Актогае отвалов несколько). */
126	    wasteExtra: (Point & { name: string })[];
127	    garage: Point;
128	    camp: Point;
129	    kpp: Point;
130	    rmc: Point;
131	    water: Point;
132	    abk: Point;
133	    lab: Point;
134	    magazine: Point;
135	    gsm: Point;
136	  };
137	  /**
138	   * Дороги на поверхности — полилинии по реальным технологическим дорогам со снимка. Совпадающие
139	   * точки разных полилиний — развилки. fromRim: первая точка соединяется с ближайшей бровкой выработки
140	   * (выезд из карьера). Площадки подключаются к ближайшей точке дорог или бровки.
141	   */
142	  haulRoads: { name: string; pts: Point[]; fromRim?: boolean }[];
143	  /** Служебные дороги: только рельеф и карта, в графе маршрутов их нет. */
144	  serviceRoads: { name: string; pts: [number, number][] }[];
145	  /** Погода и сезон: месяц года, от которого берутся климатические нормы. */
146	  weather: { month: number };
147	  truck: {
148	    /** Грузоподъёмность, т (класс CAT 793, как основной парк Актогая). */
149	    payloadT: number;
150	    speedLoadedKmh: number;
151	    speedEmptyKmh: number;
152	    /** Разброс скорости между машинами (техсостояние, водитель) — источник «сбивания в пачки». */
153	    speedFactorRange: [number, number];
154	    /** Объём бака, л. Оценка. */
155	    fuelTankL: number;
156	    /** Расход, л/ч: гружёный / порожний / работа двигателя на холостом ходу. Оценка. */
157	    fuelLoadedLph: number;
158	    fuelEmptyLph: number;
159	    fuelIdleLph: number;
160	    /** Доля топлива, при которой самосвал после разгрузки едет на заправку. */
161	    refuelThreshold: number;
162	    refuelMin: number;
163	    /** Ресурс до ТО на начало смены (диапазон), моточасы. */
164	    serviceIntervalH: [number, number];
165	    /** Вероятность поломки самосвала за смену. Оценка. */
166	    breakdownProbPerShift: number;
167	    repairMin: [number, number];
168	    /** Интервал выезда из гаража в начале смены, с. */
169	    departIntervalSec: number;
170	    /** Минимальная дистанция до впереди идущего самосвала на той же полосе, м (безопасность + габарит). */
171	    minGapM: number;
172	  };
173	  /** Взрывные работы. */
174	  blasting: {
175	    /** Время плановых взрывов, ч от начала смены (обычно в обед — меньше потерь рабочего времени). */
176	    timesH: number[];
177	    /** Разброс времени взрыва, ± мин. */
178	    jitterMin: number;
179	    /** Оцепление после взрыва (зона закрыта, экскаваторы стоят), мин. */
