    54	  const rate = ref && sim.now > 3600 ? ((total - ref.minedTotal) / (sim.now / 60 - ref.tMin)) * 60 : sim.now > 0 ? (total / sim.now) * 3600 : 0;
    55	  // Разброс — по часовым темпам, записанным в истории смены.
    56	  const tphs = hist.filter((p) => p.tMin >= 60).map((p) => p.tph);
    57	  if (tphs.length < 3) return { rate, sd: rate * 0.08 };
    58	  const mean = tphs.reduce((s, v) => s + v, 0) / tphs.length;
    59	  const sd = Math.sqrt(tphs.reduce((s, v) => s + (v - mean) ** 2, 0) / tphs.length);
    60	  return { rate, sd };
    61	}
