  1	/**
  2	 * Сценарии «что если» — одна реализация для сервиса-симулятора (команды из двойника
  3	 * org.aktogay:control) и для автономного режима интерфейса. Сценарий всегда применяется
  4	 * ко всем моделям сразу, чтобы сравнение стратегий оставалось честным.
  5	 */
  6	import { SKY, type Sky } from '../sim/weather';
  7	import type { Simulation } from '../sim/engine';
  8	
  9	/** Команда в признаке command двойника управления. */
 10	export interface Command {
 11	  value: string;
 12	  /** Объект сценария: номер экскаватора, участка дороги или id взрыва. */
 13	  /** Параметр сценария: номер объекта или, для погоды, название явления. */
 14	  arg?: number | string;
 15	  /** Длительность сценария, мин (поломка, перекрытие). По умолчанию — DEFAULT_DUR. */
 16	  dur?: number;
 17	  /** Номер команды: повтор с тем же номером не выполняется. */
 18	  seq?: number;
 19	  seed?: number;
 20	  trucks?: number;
 21	  /** Новый парк техники (reset): см. platform/fleet.ts. */
 22	  fleet?: unknown;
 23	  /** Месяц года для погоды и сезона (команда reset). */
 24	  month?: number;
 25	}
