 27	export const DEFAULT_DUR = { breakdown: 50, close_road: 40, drill_down: 240, weather: 60, power_cut: 25, storm_water: 180, leach_stop: 180, fuel_shortage: 240, no_tyres: 360, kpp_closed: 360 } as const;
 28	export const DUR_RANGE = { breakdown: [10, 180], close_road: [10, 120], drill_down: [30, 600], weather: [15, 360], power_cut: [5, 120], storm_water: [15, 240], leach_stop: [30, 720], fuel_shortage: [60, 600], no_tyres: [60, 720], kpp_closed: [60, 720] } as const;
 29	
 30	const clampDur = (kind: keyof typeof DUR_RANGE, v: number | undefined) => {
 31	  const [lo, hi] = DUR_RANGE[kind];
 32	  const d = Number(v ?? DEFAULT_DUR[kind]);
 33	  return Math.max(lo, Math.min(hi, Number.isFinite(d) ? d : DEFAULT_DUR[kind]));
 34	};
 35	
 36	/**
 37	 * Применить сценарий к моделям. Возвращает описание для журнала или null, если команда
 38	 * не сценарная (пауза, скорость, сброс — их обрабатывает тот, кто ведёт время).
 39	 */
 40	export function applyScenario(sims: Simulation[], c: Command): string | null {
 41	  const a = Number(c.arg ?? 0);
 42	  const ref = sims[0];
 43	  if (!ref) return null;
 44	  switch (c.value) {
 45	    case 'breakdown': {
 46	      const ex = ref.excavators[a];
 47	      if (!ex) return null;
 48	      const dur = clampDur('breakdown', c.dur);
 49	      for (const s of sims) s.injectExcavatorBreakdown(a, dur * 60);
 50	      return `поломка экскаватора ${ex.name} на ${dur} мин`;
 51	    }
 52	    case 'repair': {
 53	      const ok = sims.map((s) => s.repairExcavator(a)).some(Boolean);
 54	      return ok ? `отмена поломки ${ref.excavators[a]?.name ?? a}` : `${ref.excavators[a]?.name ?? a} не в ремонте`;
 55	    }
 56	    case 'close_road': {
 57	      const g = ref.layout.closureGroups[a];
 58	      if (!g) return null;
 59	      const dur = clampDur('close_road', c.dur);
 60	      const ok = sims.map((s) => s.injectRoadClosure(a, dur * 60)).every(Boolean);
 61	      return ok ? `перекрыт ${g.label} на ${dur} мин` : `нельзя перекрыть ${g.label}: сеть дорог разорвётся или участок уже закрыт`;
 62	    }
 63	    case 'open_road': {
 64	      const ok = sims.map((s) => s.openRoad(a)).some(Boolean);
 65	      return ok ? `открыт ${ref.layout.closureGroups[a]?.label ?? a}` : 'участок не был закрыт';
 66	    }
 67	    case 'power_cut': {
 68	      const dur = clampDur('power_cut', c.dur);
 69	      for (const s of sims) s.injectPowerCut(dur * 60);
 70	      return `отключение электроснабжения на ${dur} мин`;
 71	    }
 72	    case 'fuel_shortage': {
 73	      const dur = clampDur('fuel_shortage', c.dur);
 74	      for (const s of sims) s.injectFuelShortage(dur * 60);
 75	      return `перебои с топливом: завоз остановлен на ${dur} мин`;
 76	    }
 77	    case 'fuel_restore':
 78	      for (const s of sims) s.fuelDepot.supplyCutLeft = 0;
 79	      return 'завоз топлива возобновлён';
 80	    case 'no_tyres': {
 81	      const dur = clampDur('no_tyres', c.dur);
 82	      for (const s of sims) s.injectNoTyres(dur * 60);
 83	      return `нет шин на складе РМЦ, поставка через ${dur} мин`;
 84	    }
 85	    case 'tyres_restore':
 86	      for (const s of sims) s.repairShop.tyreCutLeft = 1;
 87	      return 'шины поставлены';
 88	    case 'kpp_closed': {
 89	      const dur = clampDur('kpp_closed', c.dur);
 90	      for (const s of sims) s.injectCheckpointClosed(dur * 60);
 91	      return `КПП закрыт на ${dur} мин`;
 92	    }
 93	    case 'kpp_open':
 94	      for (const s of sims) s.checkpoint.closedLeft = Math.min(s.checkpoint.closedLeft, 1);
 95	      return 'КПП открыт';
 96	    case 'storm_water': {
 97	      const dur = clampDur('storm_water', c.dur);
 98	      // arg: 0 — ливень, 1 — сильное снеготаяние; приток в пруд, м³/ч.
 99	      const rate = a >= 1 ? 70_000 : 120_000;
100	      for (const s of sims) s.injectStormWater(rate, dur * 60);
101	      return `${a >= 1 ? 'снеготаяние' : 'ливень'}: приток ${rate.toLocaleString('ru-RU')} м³/ч в пруд на ${dur} мин`;
102	    }
103	    case 'leach_stop': {
104	      const dur = clampDur('leach_stop', c.dur);
105	      for (const s of sims) s.injectLeachStop(dur * 60);
106	      return `орошение карт остановлено на ${dur} мин`;
107	    }
108	    case 'weather': {
109	      const sky = String(c.arg ?? 'blizzard') as Sky;
110	      if (!(sky in SKY)) return null;
111	      const dur = clampDur('weather', c.dur);
112	      for (const s of sims) s.weather.force(s, sky, dur * 60);
113	      return `погода: ${SKY[sky].ru} на ${dur} мин`;
114	    }
115	    case 'blast': {
116	      const ex = ref.excavators[a];
117	      if (!ex) return null;
118	      for (const s of sims) s.scheduleBlast(a, s.cfg.blasting.warnMin * 60);
119	      return `объявлен взрыв у ${ex.name} через ${ref.cfg.blasting.warnMin} мин`;
120	    }
121	    case 'cancel_blast': {
122	      const ok = sims.map((s) => s.cancelBlast(a)).some(Boolean);
123	      return ok ? `отменён взрыв #${a}` : `взрыв #${a} уже завершён`;
124	    }
125	    case 'drill_down': {
126	      // arg: 0 — БУ-1, 1 — БУ-2, 2 — оба станка.
127	      const dur = clampDur('drill_down', c.dur);
128	      const ids = a === 2 ? [0, 1] : [a];
129	      for (const s of sims) for (const i of ids) s.drill.breakRig(i, dur * 60);
130	      const names = ids.map((i) => ref.drill.rigs[i]?.name).join(' и ');
131	      for (const s of sims) s.addLog(`Поломка бурового станка ${names}, ремонт ~${dur} мин — бурение блоков остановлено`, 'alarm');
132	      return `поломка бурового станка ${names} на ${dur} мин`;
133	    }
134	    case 'drill_repair': {
135	      const ok = sims.map((s) => s.drill.repairRig(a)).some(Boolean);
136	      return ok ? `отмена поломки ${ref.drill.rigs[a]?.name}` : `${ref.drill.rigs[a]?.name ?? a} не в ремонте`;
137	    }
138	    case 'cancel_all':
139	      for (const s of sims) {
140	        s.drill.rigs.forEach((g) => s.drill.repairRig(g.id));
141	        s.excavators.forEach((ex) => s.repairExcavator(ex.id));
142	        s.layout.closureGroups.forEach((_, g) => s.openRoad(g));
143	        s.blasts.filter((b) => b.phase === 'warning' || b.phase === 'active').forEach((b) => s.cancelBlast(b.id));
144	        s.fuelDepot.supplyCutLeft = 0;
145	        if (s.repairShop.tyreCutLeft > 0) s.repairShop.tyreCutLeft = 1;
146	        if (s.checkpoint.closedLeft > 0) s.checkpoint.closedLeft = 1;
147	      }
148	      return 'все сценарии отменены';
149	    default:
150	      return null;
151	  }
152	}
