154	/** Что сейчас нарушает нормальную работу рудника (по одной модели — события у всех общие). */
155	export interface ActiveDeviation {
156	  kind: 'breakdown' | 'closure' | 'blast' | 'drill' | 'nostock' | 'supply';
157	  /** Команда отмены и её аргумент (нет — отклонение снимается само). */
158	  undo: { value: string; arg: number } | null;
159	  title: string;
160	  detail: string;
161	  /** Осталось, с (до конца поломки/закрытия/оцепления или до взрыва). */
162	  leftSec: number;
163	  phase?: 'warning' | 'active';
164	}
165	
166	export function activeDeviations(sim: Simulation): ActiveDeviation[] {
167	  const out: ActiveDeviation[] = [];
168	  for (const ex of sim.excavators) {
169	    if (ex.state !== 'broken') continue;
170	    out.push({
171	      kind: 'breakdown',
172	      undo: { value: 'repair', arg: ex.id },
173	      title: `Поломка экскаватора ${ex.name}`,
174	      detail: 'Экскаватор стоит, его самосвалы ждут или перераспределяются',
175	      leftSec: Math.max(0, ex.brokenLeft),
176	    });
177	  }
178	  for (const g of sim.drill.rigs) {
179	    if (g.state !== 'broken') continue;
180	    out.push({
181	      kind: 'drill',
182	      undo: { value: 'drill_repair', arg: g.id },
183	      title: `Поломка бурового станка ${g.name}`,
184	      detail: g.target !== null ? `Блок у ${sim.excavators[g.target]?.name}: ${sim.drill.blocks[g.target].holesDone}/${sim.drill.blocks[g.target].holesTotal} скважин` : 'Бурение остановлено',
185	      leftSec: Math.max(0, g.brokenLeft),
186	    });
187	  }
188	  for (const ex of sim.excavators) {
189	    if (ex.state !== 'nostock') continue;
190	    out.push({
191	      kind: 'nostock',
192	      undo: null,
193	      title: `${ex.name}: нет взорванной массы`,
194	      detail: 'Экскаватор стоит до взрыва обуренного блока',
195	      leftSec: 0,
196	    });
197	  }
198	  const groups = sim.layout.closureGroups;
199	  for (const c of sim.closures) {
200	    const g = groups.findIndex((x) => x.label === c.label);
201	    if (g < 0) continue; // закрытие из-за взрыва показываем вместе со взрывом
202	    out.push({
203	      kind: 'closure',
204	      undo: { value: 'open_road', arg: g },
205	      title: `Перекрыт ${c.label}`,
206	      detail: 'Маршруты строятся в объезд',
207	      leftSec: Math.max(0, c.until - sim.now),
208	    });
209	  }
210	  for (const b of sim.blasts) {
211	    if (b.phase !== 'warning' && b.phase !== 'active') continue;
212	    const names = b.exIds.map((i) => sim.excavators[i]?.name).filter(Boolean).join(', ');
213	    out.push({
214	      kind: 'blast',
215	      undo: { value: 'cancel_blast', arg: b.id },
216	      title: `${b.label} #${b.id}${b.manual ? '' : ' (плановый)'}`,
217	      detail: b.phase === 'warning' ? `Предупреждение, техника выводится из зоны ${b.radius} м${names ? ` · ${names}` : ''}` : `Оцепление ${b.radius} м${names ? ` · стоят ${names}` : ''}`,
218	      leftSec: Math.max(0, b.phase === 'warning' ? b.t - sim.now : b.t + b.dur - sim.now),
219	      phase: b.phase,
220	    });
221	  }
222	  const d = sim.fuelDepot;
223	  if (d.supplyCutLeft > 0 || d.stockM3 <= 0) {
224	    out.push({
225	      kind: 'supply',
226	      undo: d.supplyCutLeft > 0 ? { value: 'fuel_restore', arg: 0 } : null,
227	      title: 'Перебои с топливом',
228	      detail: d.stockM3 <= 0 ? `Склад ГСМ пуст: ждут топлива ${d.waitingNow} самосв.` : `На складе ГСМ ${Math.round(d.stockM3)} м³, завоза нет`,
229	      leftSec: d.supplyCutLeft,
230	    });
231	  }
232	  const r = sim.repairShop;
233	  if (r.tyreCutLeft > 0) {
234	    out.push({ kind: 'supply', undo: { value: 'tyres_restore', arg: 0 }, title: 'Нет шин на складе РМЦ', detail: 'Ремонт шин ждёт поставку', leftSec: r.tyreCutLeft });
235	  }
236	  const k = sim.checkpoint;
237	  if (k.closedLeft > 0) {
238	    out.push({
239	      kind: 'supply',
240	      undo: { value: 'kpp_open', arg: 0 },
241	      title: 'КПП закрыт',
242	      detail: `Реагентов на фабрике на ${k.reagentsH.toFixed(1)} ч${k.reagentFactor < 1 ? ` — переработка ${Math.round(k.reagentFactor * 100)} %` : ''}`,
243	      leftSec: k.closedLeft,
244	    });
245	  }
246	  return out;
247	}
